func (q *Queries) ListWorkloads(ctx context.Context) ([]Workload, error) {
	rows, err := q.db.Query(ctx, listWorkloads)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Workload{}
	for rows.Next() {
		var i Workload
		if err := rows.Scan(
			&i.ID,
			&i.RegionID,
			&i.ProvisioningTokenID,
			&i.Hostname,
			&i.EnrolledAt,
			&i.CredentialSerial,
			&i.CredentialExpiresAt,
			&i.LastRenewedAt,
			&i.Mode,
			&i.Facts,
			&i.AgentVersion,
			&i.AgentCapabilities,
			&i.LastSeenAt,
			&i.SyncState,
			&i.AppliedPolicyVersion,
			&i.SyncError,
			&i.DroppedFlowRecords,
			&i.CredentialRenewalError,
			&i.LastSnapshotSentAt,
			&i.LastAckedAt,
			&i.LastApplyFailedAt,
			&i.SourceOverruns,
			&i.ClockSkewOffsetMs,
			&i.ClockSkewObservedAt,
			&i.ClockSkewCurrent,
			&i.OwnedTableState,
			&i.OwnedTableAbsentSince,
			&i.LastFlowReportAt,
			&i.LateRenewalAt,
			&i.LateRenewalExpiredAt,
			&i.LastHeartbeatAt,
			&i.AgentStartedAt,
			&i.RetiredAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

